"use client";

import Image from "next/image";
import Link from "next/link";
import { useCallback, useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";

import { AdminShell } from "../../ui";
import { type AdminLocale } from "../../admin-locale";
import { RetailProductDetail } from "@/src/components/retail-product-detail";
import { toRetailProduct } from "@/src/data/retail/product-view-model";
import { ProductLogisticsManager } from "./product-logistics-admin";

type Row = Record<string, unknown>;
type PageKind = "list" | "new" | "overview" | "content" | "styles" | "variants" | "pricing" | "logistics" | "media" | "preview";
type RetailLocaleText = { en: string; ar: string; zh: string };
type ContentDetail = { label: RetailLocaleText; value: RetailLocaleText };
type APlusModule = { eyebrow: RetailLocaleText; title: RetailLocaleText; body: RetailLocaleText; image: string };
const key = () => crypto.randomUUID();

async function api(path: string, method = "GET", body?: unknown) {
  const response = await fetch(path, { method, headers: body ? { "content-type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined, cache: "no-store" });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.ok) throw new Error(String(data.error ?? "request_failed"));
  return data as Row;
}

function storedLocale(): AdminLocale { return typeof window !== "undefined" && localStorage.getItem("retail_admin_locale") === "zh" ? "zh" : "en"; }
function productName(product: Row, locale: AdminLocale) { return String((locale === "zh" ? product.title_zh : product.title_en) ?? product.title_en ?? product.sku ?? "—"); }
function money(amount: unknown, locale: AdminLocale) { const value = Number(amount); return Number.isFinite(value) ? new Intl.NumberFormat(locale === "zh" ? "zh-CN" : "en-US", { style: "currency", currency: "USD" }).format(value / 100) : "—"; }

const labels = {
  en: { products: "Products", new: "New product", overview: "Product information", content: "Content & A+", styles: "Styles (SKC)", variants: "Variants (SKU)", pricing: "Price & inventory", media: "Media", preview: "Product page preview", loadFailed: "Could not load catalogue.", saved: "Saved.", saveFailed: "Could not save changes.", create: "Create draft", save: "Save changes", noProducts: "No retail products yet.", productCode: "Product code", slug: "Public URL slug", titleEn: "Product name (English)", titleAr: "Product name (Arabic)", titleZh: "Product name (Chinese)", descriptionEn: "Description (English)", descriptionAr: "Description (Arabic)", descriptionZh: "Description (Chinese)", status: "Status", draft: "Draft", published: "Published", archived: "Archived", openPreview: "Open public product page", previewDraft: "Draft preview — not public", sku: "SKU", price: "Price (USD cents)", onHand: "On-hand", reserved: "Reserved", available: "Available", addStyle: "Add style", addSku: "Add SKU", styleName: "Style name", styleCode: "Style code", styleStatus: "Style status", optionName: "Option name", optionValue: "Option value", optionNameZh: "Option name (Chinese)", optionValueZh: "Option value (Chinese)", addOption: "Add option", remove: "Remove", selectStyle: "Style", noStyles: "No styles yet. Add a style before attaching SKU variants.", noVariants: "No SKU variants yet.", upload: "Upload image", imageAlt: "Image alt text (English)", file: "Image file", productPage: "Retail product page", gallery: "Product gallery", chooseProduct: "Choose a product", manage: "Manage", productDetails: "Product details", skuHelp: "Each SKU is the sellable, priced, and stocked variant. Options are entered as fields, never JSON.", styleHelp: "An SKC is a style/colour family. It can contain many sellable SKUs.", pricingHelp: "Prices and stock belong to SKU variants. Product totals are compatibility mirrors.", mediaHelp: "Images are shared product merchandising media. The first image is the main product image.", publicLinkHelp: "A public product link is available only after the product is published.", emptyPreview: "Add product details and SKU variants to review the retail product page.", contentHelp: "Write customer-facing content separately from the basic product record. Each item can be localized in English, Arabic, and Chinese.", highlights: "Highlights", details: "Specifications", aPlus: "A+ content", addHighlight: "Add highlight", addDetail: "Add specification", addModule: "Add A+ module", label: "Label", value: "Value", eyebrow: "Eyebrow (optional)", body: "Body", image: "Existing media image (optional)", noContent: "No content yet. Add a highlight, specification, or A+ module to begin.", validation: "Complete English, Arabic, and Chinese for every non-empty content field.", limit: "This section has reached its limit.", previewContent: "Preview product page", mediaReferenced: "Used by A+ content", unlinkDelete: "Unlink from A+ and delete", imageReferencedError: "This image is used by A+ content. Unlink it before deleting.", },
  zh: { products: "商品", new: "新建商品", overview: "商品资料", content: "内容与 A+", styles: "款式（SKC）", variants: "变体（SKU）", pricing: "价格与库存", media: "媒体", preview: "商品详情页预览", loadFailed: "无法加载商品目录。", saved: "已保存。", saveFailed: "保存失败。", create: "创建草稿", save: "保存修改", noProducts: "暂时没有零售商品。", productCode: "商品编码", slug: "公开链接标识", titleEn: "商品名称（英文）", titleAr: "商品名称（阿拉伯文）", titleZh: "商品名称（中文）", descriptionEn: "详情描述（英文）", descriptionAr: "详情描述（阿拉伯文）", descriptionZh: "详情描述（中文）", status: "状态", draft: "草稿", published: "已发布", archived: "已归档", openPreview: "打开公开商品详情页", previewDraft: "草稿预览 — 不公开", sku: "SKU", price: "价格（美元分）", onHand: "在库", reserved: "已预占", available: "可售", addStyle: "新增款式", addSku: "新增 SKU", styleName: "款式名称", styleCode: "款式编码", styleStatus: "款式状态", optionName: "规格名称", optionValue: "规格值", optionNameZh: "规格名称（中文）", optionValueZh: "规格值（中文）", addOption: "新增规格", remove: "删除", selectStyle: "所属款式", noStyles: "还没有 SKC 款式。请先建立款式，再挂 SKU 变体。", noVariants: "还没有 SKU 变体。", upload: "上传图片", imageAlt: "图片替代文字（英文）", file: "图片文件", productPage: "零售商品详情页", gallery: "商品图库", chooseProduct: "选择商品", manage: "管理", productDetails: "商品详情", skuHelp: "SKU 是真正可售、定价和扣库存的变体；规格通过字段编辑，不使用 JSON。", styleHelp: "SKC 是款式/颜色族，可在一个款式下挂多个可售 SKU。", pricingHelp: "价格与库存归属 SKU；商品总数只保留兼容镜像。", mediaHelp: "图片属于商品共同的陈列素材；第一张为主图。", publicLinkHelp: "仅已发布商品可访问公开商品详情页。", emptyPreview: "补充商品资料和 SKU 变体后，即可在这里检查零售商品详情页。", contentHelp: "将面向顾客的内容与基础商品资料分开维护。每项可填写英文、阿拉伯文和中文。", highlights: "卖点", details: "规格", aPlus: "A+ 内容", addHighlight: "新增卖点", addDetail: "新增规格", addModule: "新增 A+ 模块", label: "标签", value: "内容", eyebrow: "眉题（可选）", body: "正文", image: "引用现有媒体图片（可选）", noContent: "暂未填写内容。请添加卖点、规格或 A+ 模块。", validation: "请完整填写每个非空内容字段的英文、阿拉伯文和中文。", limit: "此部分已达到数量上限。", previewContent: "预览商品详情页", mediaReferenced: "A+ 引用中", unlinkDelete: "解除 A+ 引用并删除", imageReferencedError: "这张图片正在被 A+ 内容引用，请先解除引用再删除。", },
} as const;
type Copy = Record<keyof typeof labels.en, string>;

export function ProductCatalogAdmin({ kind, productId }: { kind: PageKind; productId?: string }) {
  const [locale, setLocaleState] = useState<AdminLocale>(storedLocale);
  const [products, setProducts] = useState<Row[]>([]);
  const [message, setMessage] = useState("");
  const load = useCallback(async () => { const result = await api("/api/admin/retail/products"); setProducts((result.products as Row[] | undefined) ?? []); }, []);
  useEffect(() => { let active = true; void api("/api/admin/retail/products").then((result) => { if (active) setProducts((result.products as Row[] | undefined) ?? []); }).catch(() => { if (active) setMessage(labels[storedLocale()].loadFailed); }); return () => { active = false; }; }, []);
  const localeChange = (next: AdminLocale) => { localStorage.setItem("retail_admin_locale", next); setLocaleState(next); };
  const product = useMemo(() => products.find((row) => String(row.public_id) === productId), [products, productId]);
  const t = labels[locale];
  return <AdminShell section="products" locale={locale} onLocale={localeChange} refresh={() => void load()}>
    <main className="mx-auto max-w-7xl px-5 py-7 sm:px-8">
      {kind === "list" ? <ProductList products={products} locale={locale} t={t} /> : kind === "new" ? <ProductEditor t={t} onCreated={() => void load()} /> : productId ? <ProductWorkspace kind={kind} productId={productId} product={product} locale={locale} t={t} reload={() => void load()} /> : null}
      {message && <p className="mt-4 text-sm text-red-700" role="alert">{message}</p>}
    </main>
  </AdminShell>;
}

function ProductList({ products, locale, t }: { products: Row[]; locale: AdminLocale; t: Copy }) {
  return <><header className="mb-7 flex flex-wrap items-start justify-between gap-4"><div><p className="text-sm text-muted">{t.products}</p><h1 className="noor-title text-3xl">{t.productDetails}</h1><p className="mt-2 text-sm text-muted">{locale === "zh" ? "每个商品都有独立资料、SKC 款式、SKU、价格库存、媒体及详情页预览。" : "Each product has separate information, SKCs, SKUs, price & stock, media, and a detail-page preview."}</p></div><Link className="rounded-md bg-accent px-4 py-2 text-sm text-white" href="/admin/retail/products/new">{t.new}</Link></header>
    <section className="overflow-x-auto rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-3"><table className="w-full text-left text-sm"><thead><tr className="text-muted"><th className="p-3">{t.productCode}</th><th className="p-3">{t.productDetails}</th><th className="p-3">{t.status}</th><th className="p-3">{t.price}</th><th className="p-3" /></tr></thead><tbody>{products.map((item) => <tr className="border-t border-[#e8ded1]" key={String(item.public_id)}><td className="p-3 font-medium">{String(item.sku)}</td><td className="p-3"><p>{productName(item, locale)}</p><p className="mt-1 text-xs text-muted">/{String(item.slug)}</p></td><td className="p-3">{String(item.status)}</td><td className="p-3">{money(item.amount_minor, locale)}</td><td className="p-3 text-right"><Link className="rounded-md border border-[#cdbda9] px-3 py-2" href={`/admin/retail/products/${String(item.public_id)}`}>{t.manage}</Link></td></tr>)}{!products.length && <tr><td className="p-8 text-muted" colSpan={5}>{t.noProducts}</td></tr>}</tbody></table></section></>;
}

function ProductNav({ productId, active, t }: { productId: string; active: PageKind; t: Copy }) {
  const normalizedActive: PageKind = ["styles", "variants", "pricing", "media"].includes(active) ? "overview" : active;
  const nav: Array<[PageKind, string, string]> = [
    ["overview", t === labels.zh ? "编辑商品" : "Edit product", ""],
    ["content", t.content, "content"],
    ["logistics", t === labels.zh ? "物流与报关" : "Logistics & customs", "logistics"],
    ["preview", t.preview, "preview"],
  ];
  return <nav className="mb-6 flex gap-2 overflow-x-auto border-b border-[#dfd2c0] pb-3" aria-label={t.productDetails}>{nav.map(([id, label, path]) => <Link className={`shrink-0 rounded-md px-3 py-2 text-sm ${normalizedActive === id ? "bg-[#eadcc8] font-semibold text-[#5a442d]" : "text-[#65584a] hover:bg-[#f1e7da]"}`} href={`/admin/retail/products/${productId}${path ? `/${path}` : ""}`} key={id}>{label}</Link>)}</nav>;
}

function ProductWorkspace({ kind, productId, product, locale, t, reload }: { kind: PageKind; productId: string; product?: Row; locale: AdminLocale; t: Copy; reload: () => void }) {
  return <><Link className="text-sm text-[#6f4e37] underline" href="/admin/retail/products">← {t.products}</Link><header className="mb-5 mt-3 flex flex-wrap items-start justify-between gap-3"><div><h1 className="noor-title text-3xl">{product ? productName(product, locale) : t.productDetails}</h1><p className="mt-1 text-sm text-muted">{product ? `${String(product.sku)} · ${String(product.status)}` : "…"}</p></div>{product?.status === "published" ? <a className="rounded-md border border-[#cdbda9] px-3 py-2 text-sm" href={`/zh/shop/${String(product.slug)}`} target="_blank" rel="noreferrer">{t.openPreview}</a> : <span className="rounded-md border border-[#dfd2c0] px-3 py-2 text-sm text-muted">{t.previewDraft}</span>}</header><ProductNav productId={productId} active={kind} t={t} />
    {kind === "overview" && product && <div className="space-y-5">
      <WorkspaceSection title={t.overview} description={t === labels.zh ? "顾客看到的名称、链接、状态和基础描述。" : "Customer-facing name, URL, status, and core description."} open><ProductEditor product={product} t={t} onCreated={reload} /></WorkspaceSection>
      <WorkspaceSection title={t === labels.zh ? "商品图片" : "Product images"} description={t === labels.zh ? "在当前商品内直接上传和排序；第一张图片就是商品主图。视频需要独立转码与播放链路，当前不会伪装成图片上传。" : "Upload and order images on this product. The first image is the product cover. Video needs a separate transcoding and playback path and is not disguised as an image upload."} open><MediaManager productId={productId} product={product} t={t} reload={reload} /></WorkspaceSection>
      <WorkspaceSection title={t === labels.zh ? "款式、SKU、价格与库存" : "Styles, SKUs, price & inventory"} description={t === labels.zh ? "SKC 是款式族；SKU 是真正定价、扣库存和发货的可售变体。" : "An SKC is a style family; a SKU is the sellable, priced, stocked variant."}><div className="space-y-8"><StyleManager productId={productId} product={product} t={t} /><VariantManager productId={productId} locale={locale} t={t} mode="variants" /><VariantManager productId={productId} locale={locale} t={t} mode="pricing" /></div></WorkspaceSection>
    </div>}
    {kind === "content" && product && <AdminProductContent productId={productId} product={product} t={t} reload={reload} />}
    {kind === "styles" && <StyleManager productId={productId} product={product} t={t} />}
    {kind === "variants" && <VariantManager productId={productId} locale={locale} t={t} mode="variants" />}
    {kind === "pricing" && <VariantManager productId={productId} locale={locale} t={t} mode="pricing" />}
    {kind === "logistics" && <ProductLogisticsManager productId={productId} locale={locale} />}
    {kind === "media" && <MediaManager productId={productId} product={product} t={t} reload={reload} />}
    {kind === "preview" && <AdminProductPreview productId={productId} product={product} locale={locale} t={t} />}
  </>;
}

function WorkspaceSection({ title, description, open = false, children }: { title: string; description: string; open?: boolean; children: ReactNode }) {
  return <details open={open} className="group rounded-2xl border border-[#dfd2c0] bg-white shadow-sm">
    <summary className="cursor-pointer list-none px-5 py-4"><div className="flex items-center justify-between gap-4"><div><h2 className="text-lg font-semibold">{title}</h2><p className="mt-1 text-sm text-muted">{description}</p></div><span aria-hidden="true" className="text-xl text-[#6f4e37] group-open:rotate-45">+</span></div></summary>
    <div className="border-t border-[#eadfd2] p-5">{children}</div>
  </details>;
}

const blankLocaleText = (): RetailLocaleText => ({ en: "", ar: "", zh: "" });
const blankDetail = (): ContentDetail => ({ label: blankLocaleText(), value: blankLocaleText() });
const blankAPlus = (): APlusModule => ({ eyebrow: blankLocaleText(), title: blankLocaleText(), body: blankLocaleText(), image: "" });
const localeText = (value: unknown): RetailLocaleText => {
  const record = value && typeof value === "object" ? value as Row : {};
  return { en: String(record.en ?? ""), ar: String(record.ar ?? ""), zh: String(record.zh ?? "") };
};
const nonEmptyLocaleText = (value: RetailLocaleText) => Object.values(value).some((entry) => entry.trim());
const completeLocaleText = (value: RetailLocaleText) => Object.values(value).every((entry) => entry.trim());
const contentRows = <T,>(value: unknown, map: (item: unknown) => T) => Array.isArray(value) ? value.map(map) : [];

export function AdminProductContent({ productId, product, t, reload }: { productId: string; product: Row; t: Copy; reload: () => void }) {
  const source = product.content && typeof product.content === "object" ? product.content as Row : product;
  const initial = () => ({
    highlights: contentRows(source.highlights ?? source.pdp_highlights ?? source.highlight_items, localeText),
    details: contentRows(source.details ?? source.pdp_details ?? source.specifications, (item) => { const row = item && typeof item === "object" ? item as Row : {}; return { label: localeText(row.label), value: localeText(row.value) }; }),
    aPlus: contentRows(source.aPlus ?? source.pdp_a_plus ?? source.a_plus ?? source.a_plus_modules, (item) => { const row = item && typeof item === "object" ? item as Row : {}; return { eyebrow: localeText(row.eyebrow), title: localeText(row.title), body: localeText(row.body), image: String(row.image ?? "") }; }),
  });
  const [form, setForm] = useState(initial);
  const [result, setResult] = useState("");
  const [busy, setBusy] = useState(false);
  const validationMessage = t === labels.zh ? "请完整填写每个非空内容字段的英文、阿拉伯文和中文。" : t === labels.en ? "Complete English, Arabic, and Chinese for every non-empty content field." : t.validation;
  const images = Array.isArray(product.images) ? product.images as Row[] : [];
  const mediaChoices = images.map((image) => ({ value: String(image.url ?? image.image_url ?? ""), label: String(image.alt_en ?? image.url ?? image.image_url ?? "") })).filter((image) => image.value);
  const changeHighlight = (index: number, locale: keyof RetailLocaleText, value: string) => setForm((current) => ({ ...current, highlights: current.highlights.map((item, at) => at === index ? { ...item, [locale]: value } : item) }));
  const changeDetail = (index: number, field: keyof ContentDetail, locale: keyof RetailLocaleText, value: string) => setForm((current) => ({ ...current, details: current.details.map((item, at) => at === index ? { ...item, [field]: { ...item[field], [locale]: value } } : item) }));
  const changeAPlus = (index: number, field: "eyebrow" | "title" | "body", locale: keyof RetailLocaleText, value: string) => setForm((current) => ({ ...current, aPlus: current.aPlus.map((item, at) => at === index ? { ...item, [field]: { ...item[field], [locale]: value } } : item) }));
  const valid = () => form.highlights.filter(nonEmptyLocaleText).every(completeLocaleText)
    && form.details.filter((item) => nonEmptyLocaleText(item.label) || nonEmptyLocaleText(item.value)).every((item) => completeLocaleText(item.label) && completeLocaleText(item.value))
    && form.aPlus.filter((item) => nonEmptyLocaleText(item.eyebrow) || nonEmptyLocaleText(item.title) || nonEmptyLocaleText(item.body) || item.image).every((item) => (!nonEmptyLocaleText(item.eyebrow) || completeLocaleText(item.eyebrow)) && completeLocaleText(item.title) && completeLocaleText(item.body) && (!item.image || item.image.startsWith("https://")));
  const save = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); setResult(""); if (!valid()) { setResult(validationMessage); return; } setBusy(true); try { await api(`/api/admin/retail/products/${productId}`, "PATCH", { action: "pdp_content", highlights: form.highlights.filter(nonEmptyLocaleText), details: form.details.filter((item) => nonEmptyLocaleText(item.label) || nonEmptyLocaleText(item.value)), aPlus: form.aPlus.filter((item) => nonEmptyLocaleText(item.eyebrow) || nonEmptyLocaleText(item.title) || nonEmptyLocaleText(item.body) || item.image).map(({ eyebrow, title, body, image }) => ({ ...(nonEmptyLocaleText(eyebrow) ? { eyebrow } : {}), title, body, ...(image ? { image } : {}) })), idempotencyKey: key() }); setResult(t.saved); reload(); } catch { setResult(t.saveFailed); } finally { setBusy(false); } };
  const empty = !form.highlights.length && !form.details.length && !form.aPlus.length;
  return <form className="space-y-6" onSubmit={save}><header className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-semibold">{t.content}</h2><p className="mt-1 max-w-3xl text-sm text-muted">{t.contentHelp}</p></div><Link className="rounded-md border border-[#cdbda9] px-3 py-2 text-sm" href={`/admin/retail/products/${productId}/preview`}>{t.previewContent}</Link></header>{empty && <p className="rounded-xl border border-dashed border-[#cdbda9] bg-[#fbf7f1] p-4 text-sm text-muted">{t.noContent}</p>}
    <ContentSection title={t.highlights} count={form.highlights.length} max={5} addLabel={t.addHighlight} onAdd={() => setForm((current) => ({ ...current, highlights: [...current.highlights, blankLocaleText()] }))}>{form.highlights.map((highlight, index) => <div className="grid gap-3 rounded-lg border border-[#e8ded1] bg-white p-4" key={index}><LocalizedFields label={`${t.highlights} ${index + 1}`} value={highlight} onChange={(locale, value) => changeHighlight(index, locale, value)} /><RemoveButton onClick={() => setForm((current) => ({ ...current, highlights: current.highlights.filter((_, at) => at !== index) }))} t={t} /></div>)}</ContentSection>
    <ContentSection title={t.details} count={form.details.length} max={12} addLabel={t.addDetail} onAdd={() => setForm((current) => ({ ...current, details: [...current.details, blankDetail()] }))}>{form.details.map((detail, index) => <div className="grid gap-4 rounded-lg border border-[#e8ded1] bg-white p-4" key={index}><LocalizedFields label={`${t.label} ${index + 1}`} value={detail.label} onChange={(locale, value) => changeDetail(index, "label", locale, value)} /><LocalizedFields label={`${t.value} ${index + 1}`} value={detail.value} onChange={(locale, value) => changeDetail(index, "value", locale, value)} /><RemoveButton onClick={() => setForm((current) => ({ ...current, details: current.details.filter((_, at) => at !== index) }))} t={t} /></div>)}</ContentSection>
    <ContentSection title={t.aPlus} count={form.aPlus.length} max={6} addLabel={t.addModule} onAdd={() => setForm((current) => ({ ...current, aPlus: [...current.aPlus, blankAPlus()] }))}>{form.aPlus.map((module, index) => <div className="grid gap-4 rounded-lg border border-[#e8ded1] bg-white p-4" key={index}><LocalizedFields label={`${t.eyebrow} ${index + 1}`} value={module.eyebrow} optional onChange={(locale, value) => changeAPlus(index, "eyebrow", locale, value)} /><LocalizedFields label={`${t.aPlus} title ${index + 1}`} value={module.title} onChange={(locale, value) => changeAPlus(index, "title", locale, value)} /><LocalizedTextAreas label={`${t.body} ${index + 1}`} value={module.body} onChange={(locale, value) => changeAPlus(index, "body", locale, value)} /><MediaPicker label={`${t.image} ${index + 1}`} images={mediaChoices} value={module.image} onChange={(value) => setForm((current) => ({ ...current, aPlus: current.aPlus.map((item, at) => at === index ? { ...item, image: value } : item) }))} /><RemoveButton onClick={() => setForm((current) => ({ ...current, aPlus: current.aPlus.filter((_, at) => at !== index) }))} t={t} /></div>)}</ContentSection>
    <button disabled={busy} className="rounded-md bg-accent px-4 py-2 text-sm text-white disabled:opacity-60">{t.save}</button>{result && <p className={result === validationMessage ? "text-sm text-red-700" : "text-sm"} role={result === validationMessage ? "alert" : "status"}>{result}</p>}</form>;
}

function ContentSection({ title, count, max, addLabel, onAdd, children }: { title: string; count: number; max: number; addLabel: string; onAdd: () => void; children: ReactNode }) { return <section className="rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-5"><div className="mb-4 flex items-center justify-between gap-3"><h3 className="font-semibold">{title}</h3><button type="button" disabled={count >= max} title={count >= max ? "limit" : undefined} className="rounded border border-[#cdbda9] px-3 py-1.5 text-sm disabled:opacity-50" onClick={onAdd}>{addLabel}</button></div><div className="space-y-4">{children}</div>{count >= max && <p className="mt-3 text-xs text-muted">{max} {"/"} {max}</p>}</section>; }
function LocalizedFields({ label, value, optional = false, onChange }: { label: string; value: RetailLocaleText; optional?: boolean; onChange: (locale: keyof RetailLocaleText, value: string) => void }) { return <div className="grid gap-3 md:grid-cols-3">{(["en", "ar", "zh"] as const).map((locale) => <label className="text-sm" key={locale}>{label} ({locale === "en" ? "English" : locale === "ar" ? "العربية" : "中文"}){optional ? "" : " *"}<input aria-label={`${label} ${locale}`} aria-required={optional ? undefined : true} required={!optional} dir={locale === "ar" ? "rtl" : undefined} className="mt-1 w-full rounded-md border border-[#cdbda9] bg-white p-2" value={value[locale]} onChange={(event) => onChange(locale, event.target.value)} /></label>)}</div>; }
function LocalizedTextAreas({ label, value, onChange }: { label: string; value: RetailLocaleText; onChange: (locale: keyof RetailLocaleText, value: string) => void }) { return <div className="grid gap-3 md:grid-cols-3">{(["en", "ar", "zh"] as const).map((locale) => <label className="text-sm" key={locale}>{label} ({locale === "en" ? "English" : locale === "ar" ? "العربية" : "中文"}) *<textarea aria-label={`${label} ${locale}`} aria-required="true" required dir={locale === "ar" ? "rtl" : undefined} className="mt-1 min-h-24 w-full rounded-md border border-[#cdbda9] bg-white p-2" value={value[locale]} onChange={(event) => onChange(locale, event.target.value)} /></label>)}</div>; }
function RemoveButton({ onClick, t }: { onClick: () => void; t: Copy }) { return <button type="button" className="w-fit text-sm text-[#6f4e37] underline" onClick={onClick}>{t.remove}</button>; }

function MediaPicker({ label, images, value, onChange }: { label: string; images: Array<{ value: string; label: string }>; value: string; onChange: (value: string) => void }) {
  return <fieldset><legend className="text-sm font-medium">{label}</legend><select aria-label={label} className="sr-only" value={value} onChange={(event) => onChange(event.target.value)}><option value="">No image</option>{images.map((image) => <option value={image.value} key={image.value}>{image.label}</option>)}</select><div className="mt-2 grid grid-cols-2 gap-3 sm:grid-cols-4"><button type="button" aria-pressed={!value} className={`aspect-square rounded-lg border p-2 text-xs ${!value ? "border-[#6f4e37] bg-[#f1e7da]" : "border-[#dfd2c0]"}`} onClick={() => onChange("")}>No image</button>{images.map((image) => <button type="button" aria-pressed={value === image.value} className={`overflow-hidden rounded-lg border text-left ${value === image.value ? "border-2 border-[#6f4e37]" : "border-[#dfd2c0]"}`} key={image.value} onClick={() => onChange(image.value)}><Image className="aspect-square w-full object-cover" src={image.value} alt={image.label || "Product media"} width={180} height={180} unoptimized/><span className="block truncate px-2 py-1 text-xs">{image.label || "Image"}</span></button>)}</div></fieldset>;
}

function ProductEditor({ product, t, onCreated }: { product?: Row; t: Copy; onCreated: () => void }) {
  const [form, setForm] = useState(() => ({ sku: String(product?.sku ?? ""), slug: String(product?.slug ?? ""), titleEn: String(product?.title_en ?? ""), titleAr: String(product?.title_ar ?? ""), titleZh: String(product?.title_zh ?? ""), descriptionEn: String(product?.description_en ?? ""), descriptionAr: String(product?.description_ar ?? ""), descriptionZh: String(product?.description_zh ?? ""), status: String(product?.status ?? "draft"), amountMinor: String(product?.amount_minor ?? ""), onHand: "0" }));
  const [result, setResult] = useState(""); const [busy, setBusy] = useState(false); const change = (name: string, value: string) => setForm((current) => ({ ...current, [name]: value }));
  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const files = Array.from((event.currentTarget.elements.namedItem("mediaFiles") as HTMLInputElement | null)?.files ?? []);
    let createdId = "";
    setBusy(true);
    try {
      if (product) {
        await api(`/api/admin/retail/products/${String(product.public_id)}`, "PATCH", { slug: form.slug, titleEn: form.titleEn, titleAr: form.titleAr, titleZh: form.titleZh || undefined, descriptionEn: form.descriptionEn, descriptionAr: form.descriptionAr, descriptionZh: form.descriptionZh || undefined, status: form.status, idempotencyKey: key() });
      } else {
        const made = await api("/api/admin/retail/products", "POST", { ...form, status: "draft", amountMinor: Number(form.amountMinor), onHand: Number(form.onHand), idempotencyKey: key() });
        createdId = String((made.product as Row | undefined)?.public_id ?? (made.product as Row | undefined)?.publicId ?? "");
        if (!createdId) throw new Error("missing_product_id");
        for (const file of files) {
          const media = new FormData();
          media.set("productId", createdId); media.set("idempotencyKey", key()); media.set("altEn", form.titleEn); media.set("altAr", form.titleAr); media.set("file", file);
          const response = await fetch("/api/admin/retail/media", { method: "POST", body: media });
          if (!response.ok) throw new Error("media_upload_failed");
        }
        location.assign(`/admin/retail/products/${createdId}`);
        return;
      }
      setResult(t.saved); onCreated();
    } catch {
      // A product write and its media uploads are separate durable operations.
      // Once the product exists, never leave the user on the create form where a
      // retry could create a duplicate; open the real draft for readback/recovery.
      if (createdId) {
        location.assign(`/admin/retail/products/${createdId}?mediaUpload=partial`);
        return;
      }
      setResult(t.saveFailed);
    } finally { setBusy(false); }
  };
  return <form className="rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-5" onSubmit={submit}><div className="grid gap-4 md:grid-cols-2"><Field label={t.productCode} value={form.sku} onChange={(v) => change("sku", v)} disabled={Boolean(product)} required/><Field label={t.slug} value={form.slug} onChange={(v) => change("slug", v)} required/><Field label={t.titleEn} value={form.titleEn} onChange={(v) => change("titleEn", v)} required/><Field label={t.titleAr} value={form.titleAr} onChange={(v) => change("titleAr", v)} required dir="rtl"/><Field label={t.titleZh} value={form.titleZh} onChange={(v) => change("titleZh", v)}/><label className="text-sm">{t.status}<select className="mt-1 w-full rounded-md border border-[#cdbda9] bg-white p-2" value={product ? form.status : "draft"} disabled={!product} onChange={(e) => change("status", e.target.value)}><option value="draft">{t.draft}</option><option value="published">{t.published}</option><option value="archived">{t.archived}</option></select></label>{!product && <><Field label={t.price} type="number" value={form.amountMinor} onChange={(v) => change("amountMinor", v)} required/><Field label={t.onHand} type="number" value={form.onHand} onChange={(v) => change("onHand", v)} required/><label className="md:col-span-2 rounded-xl border-2 border-dashed border-[#cdbda9] bg-white p-5 text-sm"><span className="font-medium">{t === labels.zh ? "商品图片（可多选）" : "Product images (multiple allowed)"}</span><span className="mt-1 block text-xs text-muted">{t === labels.zh ? "创建草稿时直接上传并自动关联；第一张图片会成为主图。支持 PNG、JPEG、WebP。" : "Upload while creating the draft; files are linked automatically and the first image becomes the cover. PNG, JPEG, or WebP."}</span><input name="mediaFiles" className="mt-3 block w-full" type="file" accept="image/png,image/jpeg,image/webp" multiple required /></label></>}<TextField label={t.descriptionEn} value={form.descriptionEn} onChange={(v) => change("descriptionEn", v)}/><TextField label={t.descriptionAr} value={form.descriptionAr} onChange={(v) => change("descriptionAr", v)} dir="rtl"/><TextField label={t.descriptionZh} value={form.descriptionZh} onChange={(v) => change("descriptionZh", v)}/></div><button disabled={busy} className="mt-5 rounded-md bg-accent px-4 py-2 text-sm text-white disabled:opacity-50">{busy ? (t === labels.zh ? "正在保存…" : "Saving…") : product ? t.save : t.create}</button>{result && <p className="mt-3 text-sm" role="status">{result}</p>}</form>;
}

function StyleManager({ productId, product, t }: { productId: string; product?: Row; t: Copy }) {
  const [styles, setStyles] = useState<Row[]>([]); const [form, setForm] = useState({ code: "", titleEn: "", titleZh: "", titleAr: "", primaryImageId: "", options: [{ name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }] }); const [result, setResult] = useState("");
  const load = useCallback(async () => { const result = await api(`/api/admin/retail/catalog/styles?productId=${encodeURIComponent(productId)}`); setStyles((result.styles as Row[] | undefined) ?? []); }, [productId]);
  useEffect(() => { let active = true; void api(`/api/admin/retail/catalog/styles?productId=${encodeURIComponent(productId)}`).then((result) => { if (active) setStyles((result.styles as Row[] | undefined) ?? []); }).catch(() => { if (active) setResult(t.loadFailed); }); return () => { active = false; }; }, [productId, t.loadFailed]);
  const options = () => ({ en: Object.fromEntries(form.options.filter((item) => item.name && item.value).map((item) => [item.name, item.value])), zh: Object.fromEntries(form.options.filter((item) => item.nameZh && item.valueZh).map((item) => [item.nameZh, item.valueZh])), ar: Object.fromEntries(form.options.filter((item) => item.nameAr && item.valueAr).map((item) => [item.nameAr, item.valueAr])) });
  const images = useMemo(() => Array.isArray(product?.images) ? product.images as Row[] : [], [product]);
  return <section className="space-y-5"><header><h2 className="text-xl font-semibold">{t.styles}</h2><p className="mt-1 text-sm text-muted">{t.styleHelp}</p></header><form className="rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-4" onSubmit={async (event) => { event.preventDefault(); try { await api("/api/admin/retail/catalog/styles", "POST", { productId, code: form.code, titleEn: form.titleEn, titleZh: form.titleZh || form.titleEn, titleAr: form.titleAr || form.titleEn, optionValues: options(), primaryImageId: form.primaryImageId || null, idempotencyKey: key() }); setForm({ code: "", titleEn: "", titleZh: "", titleAr: "", primaryImageId: "", options: [{ name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }] }); await load(); } catch { setResult(t.saveFailed); } }}><div className="grid gap-3 md:grid-cols-2"><Field label={t.styleCode} value={form.code} onChange={(v) => setForm({ ...form, code: v })} required/><Field label={t.styleName} value={form.titleEn} onChange={(v) => setForm({ ...form, titleEn: v })} required/><Field label={t.titleZh} value={form.titleZh} onChange={(v) => setForm({ ...form, titleZh: v })}/><Field label={t.titleAr} value={form.titleAr} onChange={(v) => setForm({ ...form, titleAr: v })}/></div><fieldset className="mt-4"><legend className="text-sm font-medium">{t.gallery}</legend><div className="mt-2 grid grid-cols-3 gap-3 sm:grid-cols-6"><button type="button" aria-pressed={!form.primaryImageId} className={`aspect-square rounded-lg border p-2 text-xs ${!form.primaryImageId ? "border-[#6f4e37] bg-[#f1e7da]" : "border-[#dfd2c0]"}`} onClick={() => setForm({ ...form, primaryImageId: "" })}>No image</button>{images.map((image) => <button type="button" aria-pressed={form.primaryImageId === String(image.id)} className={`overflow-hidden rounded-lg border ${form.primaryImageId === String(image.id) ? "border-2 border-[#6f4e37]" : "border-[#dfd2c0]"}`} key={String(image.id)} onClick={() => setForm({ ...form, primaryImageId: String(image.id) })}><Image className="aspect-square w-full object-cover" src={String(image.url)} alt={String(image.alt_en ?? "Style image")} width={140} height={140} unoptimized/></button>)}</div></fieldset><LocalizedOptionBuilder options={form.options} t={t} setOptions={(options) => setForm({ ...form, options })}/><button className="mt-4 w-fit rounded-md bg-accent px-4 py-2 text-sm text-white">{t.addStyle}</button></form>{result && <p role="status" className="text-sm">{result}</p>}<div className="grid gap-3 md:grid-cols-2">{styles.map((style) => <StyleCard key={String(style.public_id)} style={style} images={images} t={t} reload={load} />)}{!styles.length && <p className="text-sm text-muted">{t.noStyles}</p>}</div></section>;
}

function optionRows(source: unknown): LocalizedOption[] { const all = source && typeof source === "object" ? source as Record<string, Record<string, string>> : {}; const en = Object.entries(all.en ?? {}); const zh = Object.entries(all.zh ?? {}); const ar = Object.entries(all.ar ?? {}); return Array.from({ length: Math.max(en.length, zh.length, ar.length) }, (_, index) => ({ name: en[index]?.[0] ?? "", value: en[index]?.[1] ?? "", nameZh: zh[index]?.[0] ?? "", valueZh: zh[index]?.[1] ?? "", nameAr: ar[index]?.[0] ?? "", valueAr: ar[index]?.[1] ?? "" })); }
function StyleCard({ style, images, t, reload }: { style: Row; images: Row[]; t: Copy; reload: () => Promise<void> }) { const [open, setOpen] = useState(false); const [form, setForm] = useState({ code: String(style.code ?? ""), titleEn: String(style.title_en ?? ""), titleAr: String(style.title_ar ?? ""), titleZh: String(style.title_zh ?? ""), status: String(style.status ?? "active"), primaryImageId: String(style.primary_image_id ?? ""), options: optionRows(style.option_values) }); const [message, setMessage] = useState(""); const serialized = () => ({ en: Object.fromEntries(form.options.filter((x) => x.name && x.value).map((x) => [x.name, x.value])), zh: Object.fromEntries(form.options.filter((x) => x.nameZh && x.valueZh).map((x) => [x.nameZh, x.valueZh])), ar: Object.fromEntries(form.options.filter((x) => x.nameAr && x.valueAr).map((x) => [x.nameAr, x.valueAr])) }); return <article className="rounded-xl border border-[#dfd2c0] bg-white p-4">{style.style_image_url ? <Image className="float-left mr-3 h-14 w-14 rounded object-cover" src={String(style.style_image_url)} alt="" width={56} height={56} unoptimized /> : null}<p className="font-medium">{String(style.title_en)}</p><p className="mt-1 text-xs text-muted">{String(style.code)} · {String(style.variant_count ?? 0)} SKU · {String(style.status ?? "active")}</p><button type="button" className="mt-3 rounded border border-[#cdbda9] px-3 py-1 text-sm" onClick={() => setOpen(!open)}>{t.save}</button>{open && <form className="mt-4 clear-both grid gap-2" onSubmit={async (e) => { e.preventDefault(); try { await api(`/api/admin/retail/catalog/styles/${String(style.public_id)}`, "PATCH", { ...form, optionValues: serialized(), primaryImageId: form.primaryImageId || null, idempotencyKey: key() }); setMessage(t.saved); await reload(); } catch { setMessage(t.saveFailed); } }}><Field label={t.styleCode} value={form.code} onChange={(v) => setForm({ ...form, code: v })} required/><Field label={t.titleEn} value={form.titleEn} onChange={(v) => setForm({ ...form, titleEn: v })} required/><Field label={t.titleZh} value={form.titleZh} onChange={(v) => setForm({ ...form, titleZh: v })} required/><Field label={t.titleAr} value={form.titleAr} onChange={(v) => setForm({ ...form, titleAr: v })} required/><label className="text-sm">{t.status}<select value={form.status} className="mt-1 w-full rounded border p-2" onChange={(e) => setForm({ ...form, status: e.target.value })}><option value="active">active</option><option value="archived">{t.archived}</option></select></label><label className="text-sm">{t.gallery}<select value={form.primaryImageId} className="mt-1 w-full rounded border p-2" onChange={(e) => setForm({ ...form, primaryImageId: e.target.value })}><option value="">—</option>{images.map((image) => <option value={String(image.id)} key={String(image.id)}>{String(image.alt_en ?? image.id)}</option>)}</select></label><LocalizedOptionBuilder options={form.options} t={t} setOptions={(options) => setForm({ ...form, options })}/><button className="rounded bg-accent px-3 py-2 text-sm text-white">{t.save}</button>{Number(style.variant_count ?? 0) === 0 ? <button type="button" className="rounded border border-[#cdbda9] px-3 py-2 text-sm" onClick={async () => { try { await api(`/api/admin/retail/catalog/styles/${String(style.public_id)}`, "DELETE", { idempotencyKey: key() }); await reload(); } catch { setMessage(t.saveFailed); } }}>{t.remove}</button> : <p className="text-xs text-muted">{t.remove}: {String(style.variant_count)} SKU</p>}{message && <p role="status" className="text-sm">{message}</p>}</form>}</article>; }

function VariantManager({ productId, locale, t, mode }: { productId: string; locale: AdminLocale; t: Copy; mode: "variants" | "pricing" }) {
  const [variants, setVariants] = useState<Row[]>([]); const [styles, setStyles] = useState<Row[]>([]); const [result, setResult] = useState(""); const [form, setForm] = useState({ styleId: "", sku: "", titleEn: "", titleAr: "", titleZh: "", amountMinor: "", onHand: "0", options: [{ name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }] });
  const load = useCallback(async () => { const [variantsResult, styleResult] = await Promise.all([api(`/api/admin/retail/catalog/variants?productId=${encodeURIComponent(productId)}`), api(`/api/admin/retail/catalog/styles?productId=${encodeURIComponent(productId)}`)]); setVariants((variantsResult.variants as Row[] | undefined) ?? []); setStyles((styleResult.styles as Row[] | undefined) ?? []); }, [productId]);
  useEffect(() => { let active = true; void Promise.all([api(`/api/admin/retail/catalog/variants?productId=${encodeURIComponent(productId)}`), api(`/api/admin/retail/catalog/styles?productId=${encodeURIComponent(productId)}`)]).then(([variantsResult, styleResult]) => { if (!active) return; setVariants((variantsResult.variants as Row[] | undefined) ?? []); setStyles((styleResult.styles as Row[] | undefined) ?? []); }).catch(() => { if (active) setResult(t.loadFailed); }); return () => { active = false; }; }, [productId, t.loadFailed]);
  const optionValues = () => ({ en: Object.fromEntries(form.options.filter((item) => item.name && item.value).map((item) => [item.name, item.value])), ar: Object.fromEntries(form.options.filter((item) => item.nameAr && item.valueAr).map((item) => [item.nameAr, item.valueAr])), zh: Object.fromEntries(form.options.filter((item) => item.nameZh && item.valueZh).map((item) => [item.nameZh, item.valueZh])) });
  if (mode === "pricing") return <section><header><h2 className="text-xl font-semibold">{t.pricing}</h2><p className="mt-1 text-sm text-muted">{t.pricingHelp}</p></header><div className="mt-5 overflow-x-auto rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-3"><table className="w-full text-left text-sm"><thead><tr><th className="p-2">{t.sku}</th><th className="p-2">{t.price}</th><th className="p-2">{t.onHand}</th><th className="p-2">{t.reserved}</th><th className="p-2">{t.available}</th><th /></tr></thead><tbody>{variants.map((variant) => <PriceRow key={String(variant.public_id)} variant={variant} t={t} reload={load} />)}{!variants.length && <tr><td colSpan={6} className="p-5 text-muted">{t.noVariants}</td></tr>}</tbody></table></div>{result && <p role="status" className="mt-3 text-sm">{result}</p>}</section>;
  return <section className="space-y-5"><header><h2 className="text-xl font-semibold">{t.variants}</h2><p className="mt-1 text-sm text-muted">{t.skuHelp}</p></header><form className="rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-4" onSubmit={async (event) => { event.preventDefault(); try { await api("/api/admin/retail/catalog/variants", "POST", { productId, styleId: form.styleId || undefined, sku: form.sku, titleEn: form.titleEn, titleAr: form.titleAr || form.titleEn, titleZh: form.titleZh || form.titleEn, optionValues: optionValues(), amountMinor: Number(form.amountMinor), onHand: Number(form.onHand), idempotencyKey: key() }); setForm({ styleId: "", sku: "", titleEn: "", titleAr: "", titleZh: "", amountMinor: "", onHand: "0", options: [{ name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }] }); await load(); } catch { setResult(t.saveFailed); } }}><div className="grid gap-3 md:grid-cols-2"><label className="text-sm">{t.selectStyle}<select className="mt-1 w-full rounded-md border border-[#cdbda9] bg-white p-2" value={form.styleId} onChange={(e) => setForm({ ...form, styleId: e.target.value })}><option value="">—</option>{styles.map((style) => <option value={String(style.public_id)} key={String(style.public_id)}>{String((locale === "zh" ? style.title_zh : style.title_en) ?? style.title_en)}</option>)}</select></label><Field label={t.sku} value={form.sku} onChange={(v) => setForm({ ...form, sku: v })} required/><Field label={t.titleEn} value={form.titleEn} onChange={(v) => setForm({ ...form, titleEn: v })} required/><Field label={t.titleZh} value={form.titleZh} onChange={(v) => setForm({ ...form, titleZh: v })}/><Field label={t.titleAr} value={form.titleAr} onChange={(v) => setForm({ ...form, titleAr: v })}/><Field label={t.price} type="number" value={form.amountMinor} onChange={(v) => setForm({ ...form, amountMinor: v })} required/><Field label={t.onHand} type="number" value={form.onHand} onChange={(v) => setForm({ ...form, onHand: v })} required/></div><LocalizedOptionBuilder options={form.options} t={t} setOptions={(options) => setForm({ ...form, options })}/><button className="mt-4 rounded-md bg-accent px-4 py-2 text-sm text-white">{t.addSku}</button></form>{result && <p role="status" className="text-sm">{result}</p>}<div className="overflow-x-auto rounded-xl border border-[#dfd2c0] bg-white p-3"><table className="w-full text-left text-sm"><thead><tr><th className="p-2">{t.sku}</th><th className="p-2">{t.selectStyle}</th><th className="p-2">{t.price}</th><th className="p-2">{t.available}</th><th /></tr></thead><tbody>{variants.map((variant) => <tr className="border-t border-[#e8ded1]" key={String(variant.public_id)}><td className="p-2">{String(variant.sku)}<p className="text-xs text-muted">{String((locale === "zh" ? variant.title_zh : variant.title_en) ?? variant.title_en ?? "")}</p></td><td className="p-2">{String(variant.style_title_en ?? variant.style_code ?? "—")}</td><td className="p-2">{money(variant.amount_minor, locale)}</td><td className="p-2">{String(variant.available ?? "—")}</td><td className="p-2"><VariantEditor variant={variant} styles={styles} t={t} reload={load} /></td></tr>)}{!variants.length && <tr><td colSpan={5} className="p-5 text-muted">{t.noVariants}</td></tr>}</tbody></table></div></section>;
}

function VariantEditor({ variant, styles, t, reload }: { variant: Row; styles: Row[]; t: Copy; reload: () => Promise<void> }) { const [open, setOpen] = useState(false); const from = optionRows(variant.option_values); const [form, setForm] = useState({ styleId: String(variant.style_public_id ?? ""), sku: String(variant.sku ?? ""), titleEn: String(variant.title_en ?? ""), titleAr: String(variant.title_ar ?? ""), titleZh: String(variant.title_zh ?? ""), status: String(variant.status ?? "active"), options: from.length ? from : [{ name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }] }); const [message, setMessage] = useState(""); const options = () => ({ en: Object.fromEntries(form.options.filter((x) => x.name && x.value).map((x) => [x.name, x.value])), ar: Object.fromEntries(form.options.filter((x) => x.nameAr && x.valueAr).map((x) => [x.nameAr, x.valueAr])), zh: Object.fromEntries(form.options.filter((x) => x.nameZh && x.valueZh).map((x) => [x.nameZh, x.valueZh])) }); return <details open={open} onToggle={(e) => setOpen((e.target as HTMLDetailsElement).open)}><summary className="cursor-pointer text-sm text-[#6f4e37]">{t.save}</summary><form className="mt-3 grid min-w-72 gap-2 rounded border border-[#dfd2c0] p-3" onSubmit={async (e) => { e.preventDefault(); try { await api(`/api/admin/retail/catalog/variants/${String(variant.public_id)}`, "PATCH", { ...form, optionValues: options(), idempotencyKey: key() }); setMessage(t.saved); await reload(); } catch { setMessage(t.saveFailed); } }}><label className="text-sm">{t.selectStyle}<select className="mt-1 w-full rounded border p-2" value={form.styleId} onChange={(e) => setForm({ ...form, styleId: e.target.value })}>{styles.map((style) => <option key={String(style.public_id)} value={String(style.public_id)}>{String(style.title_en)}</option>)}</select></label><Field label={t.sku} value={form.sku} onChange={(v) => setForm({ ...form, sku: v })} required/><Field label={t.titleEn} value={form.titleEn} onChange={(v) => setForm({ ...form, titleEn: v })} required/><Field label={t.titleZh} value={form.titleZh} onChange={(v) => setForm({ ...form, titleZh: v })} required/><Field label={t.titleAr} value={form.titleAr} onChange={(v) => setForm({ ...form, titleAr: v })} required/><label className="text-sm">{t.status}<select className="mt-1 w-full rounded border p-2" value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })}><option value="active">active</option><option value="archived">{t.archived}</option></select></label><LocalizedOptionBuilder options={form.options} t={t} setOptions={(options) => setForm({ ...form, options })}/><button className="rounded bg-accent px-3 py-2 text-sm text-white">{t.save}</button>{message && <p role="status" className="text-sm">{message}</p>}</form></details>; }

type LocalizedOption = { name: string; value: string; nameZh: string; valueZh: string; nameAr: string; valueAr: string };
function LocalizedOptionBuilder({ options, t, setOptions }: { options: LocalizedOption[]; t: Copy; setOptions: (value: LocalizedOption[]) => void }) { return <fieldset className="mt-5"><legend className="text-sm font-medium">{t.variants}</legend><div className="mt-2 space-y-2">{options.map((item, index) => <div className="grid gap-2 md:grid-cols-7" key={index}><Field label={t.optionName} value={item.name} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, name: v } : entry))}/><Field label={t.optionValue} value={item.value} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, value: v } : entry))}/><Field label={t.optionNameZh} value={item.nameZh} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, nameZh: v } : entry))}/><Field label={t.optionValueZh} value={item.valueZh} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, valueZh: v } : entry))}/><Field label={`${t.optionName} (AR)`} value={item.nameAr} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, nameAr: v } : entry))} dir="rtl"/><Field label={`${t.optionValue} (AR)`} value={item.valueAr} onChange={(v) => setOptions(options.map((entry, i) => i === index ? { ...entry, valueAr: v } : entry))} dir="rtl"/><button type="button" className="self-end rounded-md border border-[#cdbda9] px-3 py-2 text-sm" onClick={() => setOptions(options.filter((_, i) => i !== index))}>{t.remove}</button></div>)}</div><button type="button" className="mt-3 rounded-md border border-[#cdbda9] px-3 py-2 text-sm" onClick={() => setOptions([...options, { name: "", value: "", nameZh: "", valueZh: "", nameAr: "", valueAr: "" }])}>{t.addOption}</button></fieldset>; }

function PriceRow({ variant, t, reload }: { variant: Row; t: Copy; reload: () => Promise<void> }) { const [price, setPrice] = useState(String(variant.amount_minor ?? "")); const [onHand, setOnHand] = useState(String(variant.on_hand ?? "")); const [busy, setBusy] = useState(false); return <tr className="border-t border-[#e8ded1]"><td className="p-2">{String(variant.sku)}</td><td className="p-2"><input aria-label={`${String(variant.sku)} ${t.price}`} className="w-28 rounded border p-1" type="number" value={price} onChange={(e) => setPrice(e.target.value)} /></td><td className="p-2"><input aria-label={`${String(variant.sku)} ${t.onHand}`} className="w-24 rounded border p-1" type="number" min={Number(variant.reserved ?? 0)} value={onHand} onChange={(e) => setOnHand(e.target.value)} /></td><td className="p-2">{String(variant.reserved ?? 0)}</td><td className="p-2">{String(variant.available ?? 0)}</td><td className="p-2"><button disabled={busy} className="rounded border border-[#cdbda9] px-3 py-1" onClick={async () => { setBusy(true); try { await api(`/api/admin/retail/catalog/variants/${String(variant.public_id)}`, "PATCH", { amountMinor: Number(price), onHand: Number(onHand), idempotencyKey: key() }); await reload(); } finally { setBusy(false); } }}>{t.save}</button></td></tr>; }

function MediaManager({ productId, product, t, reload }: { productId: string; product?: Row; t: Copy; reload: () => void }) {
  const [result, setResult] = useState(""); const [busy, setBusy] = useState(false); const images = Array.isArray(product?.images) ? [...product.images as Row[]].sort((a, b) => Number(a.position ?? 0) - Number(b.position ?? 0)) : [];
  const ordered = async (ids: string[]) => { setBusy(true); try { await api("/api/admin/retail/media/reorder", "PATCH", { productId, imageIds: ids, expectedVersion: Number(product?.image_version ?? product?.images_version ?? product?.version ?? 0), idempotencyKey: key() }); setResult(t.saved); reload(); } catch { setResult(t.saveFailed); } finally { setBusy(false); } };
  const referencedUrls = new Set((Array.isArray(product?.pdp_a_plus) ? product.pdp_a_plus : []).map((module) => module && typeof module === "object" ? String((module as Row).image ?? "") : "").filter(Boolean));
  const remove = async (id: string, removeReferences = false) => { setBusy(true); try { await api("/api/admin/retail/media", "DELETE", { imageId: id, removeReferences, idempotencyKey: key() }); setResult(t.saved); reload(); } catch (error) { setResult(error instanceof Error && error.message === "image is used by product PDP content" ? t.imageReferencedError : t.saveFailed); } finally { setBusy(false); } };
  return <section><header><h2 className="text-xl font-semibold">{t.media}</h2><p className="mt-1 text-sm text-muted">{t.mediaHelp}</p></header><form className="mt-5 grid gap-3 rounded-xl border border-[#dfd2c0] bg-[#fbf7f1] p-4 md:grid-cols-2" onSubmit={async (event) => { event.preventDefault(); const form = event.currentTarget; const body = new FormData(form); body.set("productId", productId); body.set("idempotencyKey", key()); setBusy(true); try { const response = await fetch("/api/admin/retail/media", { method: "POST", body }); const data = await response.json(); if (!response.ok || !data.ok) throw new Error(data.error ?? t.saveFailed); form.reset(); setResult(t.saved); reload(); } catch { setResult(t.saveFailed); } finally { setBusy(false); } }}><label className="text-sm">{t.file}<input name="file" className="mt-1 block w-full" type="file" accept="image/png,image/jpeg,image/webp" required /></label><Field label={t.imageAlt} name="altEn"/><button disabled={busy} className="w-fit self-end rounded-md bg-accent px-4 py-2 text-sm text-white">{t.upload}</button></form>{result && <p className="mt-3 text-sm" role="status">{result}</p>}<div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{images.map((image, index) => { const referenced = referencedUrls.has(String(image.url)); return <article className="overflow-hidden rounded-xl border border-[#dfd2c0] bg-white" key={String(image.id)}><Image className="aspect-square w-full object-cover" src={String(image.url)} alt={String(image.alt_en ?? "Product image")} width={500} height={500} unoptimized /><div className="p-3"><p className="text-sm">{String(image.alt_en ?? "")}</p>{referenced && <p className="mt-1 text-xs text-amber-800">{t.mediaReferenced}</p>}<div className="mt-3 flex flex-wrap gap-2"><button type="button" disabled={busy || index === 0} className="rounded border border-[#cdbda9] px-2 py-1 text-sm" onClick={() => void ordered(images.map((entry) => String(entry.id)).map((id, at, all) => at === index ? all[index - 1] : at === index - 1 ? all[index] : id))}>↑</button><button type="button" disabled={busy || index === images.length - 1} className="rounded border border-[#cdbda9] px-2 py-1 text-sm" onClick={() => void ordered(images.map((entry) => String(entry.id)).map((id, at, all) => at === index ? all[index + 1] : at === index + 1 ? all[index] : id))}>↓</button><button type="button" disabled={busy || index === 0} className="rounded border border-[#cdbda9] px-2 py-1 text-sm" onClick={() => void ordered([String(image.id), ...images.filter((entry) => entry.id !== image.id).map((entry) => String(entry.id))])}>{t.gallery}</button><button type="button" disabled={busy} className="rounded border border-[#cdbda9] px-2 py-1 text-sm" onClick={() => void remove(String(image.id))}>{t.remove}</button>{referenced && <button type="button" disabled={busy} className="rounded border border-amber-700 px-2 py-1 text-sm text-amber-900" onClick={() => void remove(String(image.id), true)}>{t.unlinkDelete}</button>}</div></div></article>; })}</div></section>;
}

export function AdminProductPreview({ productId, product, locale, t }: { productId: string; product?: Row; locale: AdminLocale; t: Copy }) {
  const [variants, setVariants] = useState<Row[]>([]); const [styles, setStyles] = useState<Row[]>([]);
  useEffect(() => { void Promise.all([api(`/api/admin/retail/catalog/variants?productId=${encodeURIComponent(productId)}`), api(`/api/admin/retail/catalog/styles?productId=${encodeURIComponent(productId)}`)]).then(([v, s]) => { setVariants((v.variants as Row[] | undefined) ?? []); setStyles((s.styles as Row[] | undefined) ?? []); }).catch(() => undefined); }, [productId]);
  const images = useMemo(() => Array.isArray(product?.images) ? product.images as Row[] : [], [product]);
  const detail = useMemo(() => {
    if (!product) return undefined;
    const styleById = new Map(styles.filter((style) => style.status === "active").map((style) => [String(style.public_id), style]));
    const activeVariants = variants.filter((variant) => variant.status === "active" && styleById.has(String(variant.style_public_id)));
    return toRetailProduct({ sku: String(product.sku ?? ""), slug: String(product.slug ?? ""), title_en: String(product.title_en ?? ""), title_ar: String(product.title_ar ?? product.title_en ?? ""), title_zh: String(product.title_zh ?? product.title_en ?? ""), description_en: String(product.description_en ?? ""), description_ar: String(product.description_ar ?? product.description_en ?? ""), description_zh: String(product.description_zh ?? product.description_en ?? ""), pdp_highlights: product.pdp_highlights, pdp_details: product.pdp_details, pdp_a_plus: product.pdp_a_plus, images: images.map((image) => ({ url: String(image.url) })), variants: activeVariants.map((variant) => { const style = styleById.get(String(variant.style_public_id)); return { ...variant, style_option_values: style?.option_values, style_image_url: style?.style_image_url, style_title_en: style?.title_en ?? variant.style_title_en, style_title_ar: style?.title_ar ?? variant.style_title_ar, style_title_zh: style?.title_zh ?? variant.style_title_zh, style_position: style?.position ?? variant.style_position }; }) }, locale);
  }, [images, locale, product, styles, variants]);
  return <section><header className="mx-auto max-w-6xl px-5 pt-3"><h2 className="text-xl font-semibold">{t.productPage}</h2><p className="mt-1 text-sm text-muted">{product?.status === "published" ? t.openPreview : t.previewDraft}</p></header>{detail ? <RetailProductDetail locale={locale} product={detail} images={images.map((image) => String(image.url))} /> : <p className="mt-4 text-sm text-muted">{t.emptyPreview}</p>}</section>;
}

function Field({ label, value, onChange, name, required, disabled, type = "text", dir }: { label: string; value?: string; onChange?: (value: string) => void; name?: string; required?: boolean; disabled?: boolean; type?: string; dir?: "rtl" }) { return <label className="text-sm">{label}<input name={name} dir={dir} required={required} disabled={disabled} type={type} className="mt-1 w-full rounded-md border border-[#cdbda9] bg-white p-2 disabled:bg-[#f3ece2]" value={value} onChange={(e) => onChange?.(e.target.value)} /></label>; }
function TextField({ label, value, onChange, dir }: { label: string; value: string; onChange: (value: string) => void; dir?: "rtl" }) { return <label className="text-sm md:col-span-2">{label}<textarea dir={dir} rows={4} className="mt-1 w-full rounded-md border border-[#cdbda9] bg-white p-2" value={value} onChange={(e) => onChange(e.target.value)} /></label>; }
